      backends = backends.filter((_, i) => i !== 0)
    }
  }

  const errors = []

  for (const backend of backends) {
    try {
      console.log('[' + source + '] 尝试后端: ' + backend.name + ' ID: ' + songId + ' 音质: ' + quality)
