async function getQqMusicUrl(musicInfo, quality) {
    if (!QQ_API_KEY) throw new Error('请先配置QQ音乐API Key')

    const songId = getQqSongId(musicInfo)
    if (!songId) throw new Error('歌曲缺少ID信息')

