        if (songId.type === 'mid') {
            params.mid = songId.value
        } else {
            params.songid = songId.value
        }

        const data = await sendRequest('https://oiapi.net/api/QQ_Music', params)
        return extractQqAudioUrl(data)
    } catch (error) {
        return await tryQqQualityFallback(songId, qualityConfig.br)
    }
